      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=5.00 date=2026-02-05`,
      `PERIOD_CLOSED sheet=${sheet} by=uma period=P1 total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10 number=1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=2.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=20.00 due-total=2.00 overdue-total=0.00`,
      `CLAIM_EDITED sheet=${sheet} by=uma person=Ada amount=12.50 date=2026-03-10`,
      `CLAIM_EDITED sheet=${sheet} by=uma person=Ada amount=6.00 date=2026-02-05`,
      `CLAIM_EDITED sheet=${sheet} by=uma person=Ada amount=14.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=14.00 date=2026-03-10 number=2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=34.00 due-total=3.40 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=34.00 due-total=3.40 overdue-total=0.00`
    ]);
  });
