581	    this.reassignTo.update((chosen) => ({ ...chosen, [id]: personId }));
582	    if (this.rowError()?.id === id) this.rowError.set(null);
583	  }
584	
585	  protected setDeferDate(id: number, date: string): void {
586	    this.deferDates.update((dates) => ({ ...dates, [id]: date }));
587	    if (this.rowError()?.id === id) this.rowError.set(null);
588	  }
589	
590	  /** Defer an OPEN claim until the date typed on its row; a claim that is not OPEN, a date not after
591	   *  the sheet's today, or a claim dated in a closed period, is refused on the row. */
592	  protected async defer(claim: Claim): Promise<void> {
593	    this.rowError.set(null);
594	    const sheet = this.session.sheetId();
595	    if (!sheet) return;
596	    const until = (this.deferDates()[claim.id] ?? '').trim();
597	    if (until === '') {
598	      this.rowError.set({ id: claim.id, message: 'Type the date the claim is deferred until.' });
599	      return;
600	    }
601	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/defer`;
602	    try {
603	      const saved = await firstValueFrom(this.http.post<Claim>(url, { until }));
604	      if (this.session.sheetId() !== sheet) return;
605	      this.saved.emit(saved);
606	    } catch {
607	      this.rowError.set({
608	        id: claim.id,
609	        message: 'The claim could not be deferred: only an open claim outside a closed period can be, to a date after today.',
610	      });
611	    }
612	  }
613	
614	  /** Remind an OPEN or PENDING claim; a claim in any other status, or one already reminded on the
615	   *  sheet's today, is refused on the row. */
616	  protected async remind(claim: Claim): Promise<void> {
617	    this.rowError.set(null);
618	    const sheet = this.session.sheetId();
619	    if (!sheet) return;
620	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/remind`;
621	    try {
622	      const saved = await firstValueFrom(this.http.post<Claim>(url, {}));
623	      if (this.session.sheetId() !== sheet) return;
624	      this.saved.emit(saved);
625	    } catch {
626	      this.rowError.set({
627	        id: claim.id,
628	        message: 'The claim could not be reminded: only an open or pending claim can be, once a day.',
629	      });
630	    }
631	  }
632	
633	  protected setNewDate(id: number, date: string): void {
634	    this.newDates.update((dates) => ({ ...dates, [id]: date }));
635	    if (this.rowError()?.id === id) this.rowError.set(null);
636	  }
637	
638	  /** Re-date an OPEN or PENDING claim to the date typed on its row; anyone but a steward, a claim
639	   *  that is not OPEN or PENDING, a claim due by a day in a closed period, or a new date
640	   *  after its person's retirement, is refused on the row. */
641	  protected async redate(claim: Claim): Promise<void> {
642	    this.rowError.set(null);
643	    const sheet = this.session.sheetId();
644	    if (!sheet) return;
645	    const date = (this.newDates()[claim.id] ?? '').trim();
646	    if (date === '') {
647	      this.rowError.set({ id: claim.id, message: 'Type the date to re-date the claim to.' });
648	      return;
649	    }
650	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/redate`;
651	    try {
652	      const saved = await firstValueFrom(this.http.post<Claim>(url, { date }));
653	      if (this.session.sheetId() !== sheet) return;
654	      this.saved.emit(saved);
655	    } catch (e) {
656	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
657	      this.rowError.set({
658	        id: claim.id,
659	        message: forbidden
660	          ? 'The claim could not be re-dated: only a steward can re-date a claim.'
661	          : 'The claim could not be re-dated: only an open or pending claim outside a closed period can be, to a date not after its person retired.',
662	      });
663	    }
664	  }
665	
666	  protected setSplitAmount(id: number, amount: string): void {
667	    this.splitAmounts.update((amounts) => ({ ...amounts, [id]: amount }));
668	    if (this.rowError()?.id === id) this.rowError.set(null);
669	  }
670	
671	  /** Split the amount typed on its row off an OPEN claim: the claim keeps the rest, and the new OPEN
672	   *  claim is listed first. A claim that is not OPEN or is deferred, one in a closed period, an
673	   *  amount not above 0.00 and below the claim's, or a role that may not open a claim, is refused on
674	   *  the row. */
675	  protected async split(claim: Claim): Promise<void> {
676	    this.rowError.set(null);
677	    const sheet = this.session.sheetId();
678	    if (!sheet) return;
679	    const amount = (this.splitAmounts()[claim.id] ?? '').trim();
680	    if (!AMOUNT.test(amount) || cents(amount) <= 0 || cents(amount) >= cents(claim.amount)) {
681	      this.rowError.set({ id: claim.id, message: "Type an amount above 0.00 and below the claim's to split off." });
682	      return;
683	    }
684	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/split`;
685	    try {
686	      const result = await firstValueFrom(this.http.post<Split>(url, { amount }));
687	      if (this.session.sheetId() !== sheet) return;
688	      this.setSplitAmount(claim.id, '');
689	      this.saved.emit(result.kept);
690	      this.saved.emit(result.added);
691	    } catch (e) {
692	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
693	      this.rowError.set({
694	        id: claim.id,
695	        message: forbidden
696	          ? 'The claim could not be split: your role may not open a claim on this sheet.'
697	          : 'The claim could not be split: only an open claim outside a closed period, not deferred, can be.',
698	      });
699	    }
700	  }
701	
702	  /** Add a proof to a claim, raising its proofs count by one; a SETTLED or VOID claim, or one dated
703	   *  in a closed period, is refused on the row. */
704	  protected async addProof(claim: Claim): Promise<void> {
705	    this.rowError.set(null);
706	    const sheet = this.session.sheetId();
707	    if (!sheet) return;
708	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/proof`;
709	    try {
710	      const saved = await firstValueFrom(this.http.post<Claim>(url, null));
711	      if (this.session.sheetId() !== sheet) return;
712	      this.saved.emit(saved);
713	    } catch {
714	      this.rowError.set({
715	        id: claim.id,
716	        message: 'A proof could not be added: a settled or voided claim, or one in a closed period, takes no more.',
717	      });
718	    }
719	  }
720	
721	  /** A steward moves a DRAFT, OPEN or PENDING claim to the person chosen on its row; anyone else, a
722	   *  SETTLED or VOID claim, or no person chosen, is refused on the row. */
723	  protected async reassign(claim: Claim): Promise<void> {
724	    this.rowError.set(null);
725	    const sheet = this.session.sheetId();
726	    if (!sheet) return;
727	    const to = this.reassignTo()[claim.id] ?? '';
728	    if (to === '') {
729	      this.rowError.set({ id: claim.id, message: 'Choose the person to move the claim to.' });
730	      return;
731	    }
732	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/reassign`;
733	    try {
734	      const saved = await firstValueFrom(this.http.post<Claim>(url, { toPersonId: Number(to) }));
735	      if (this.session.sheetId() !== sheet) return;
736	      this.setReassignTo(claim.id, '');
737	      this.moved.emit(saved);
738	    } catch (e) {
739	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
740	      this.rowError.set({
741	        id: claim.id,
742	        message: forbidden
743	          ? 'The claim could not be moved: your role may not move a claim on this sheet.'
744	          : 'The claim could not be moved: a settled or voided claim, or a correction, stays where it is.',
745	      });
746	    }
747	  }
748	
749	  protected reset(): void {
750	    this.editingId.set(null);
751	    this.amount.set('');
752	    this.date.set('');
753	    this.note.set('');
754	    this.corrects.set('');
755	    this.error.set(null);
756	  }
757	
758	  /** Open, settle, approve, reject (with the reason typed on its row), void or re-settle a claim; a clerk
759	   *  settling a due above the clerk limit leaves it PENDING. A change its status does not allow, the
760	   *  user who opened it settling or approving it, anyone but a steward approving or rejecting it, or
761	   *  a reject with no reason, is refused on the row. */
762	  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
763	    this.rowError.set(null);
764	    const sheet = this.session.sheetId();
765	    if (!sheet) return;
766	    const reason = (this.rejectReasons()[claim.id] ?? '').trim();
767	    if (action === 'reject' && reason === '') {
768	      this.rowError.set({ id: claim.id, message: 'Type the reason the claim is rejected.' });
769	      return;
770	    }
771	    const url =
772	      `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims/${claim.id}/${action}`;
773	    try {
774	      const saved = await firstValueFrom(this.http.post<Claim>(url, action === 'reject' ? { reason } : null));
775	      if (this.session.sheetId() !== sheet) return;
776	      if (action === 'reject') this.setRejectReason(claim.id, '');
777	      this.saved.emit(saved);
778	    } catch (e) {
779	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
780	      this.rowError.set({
781	        id: claim.id,
782	        message:
783	          forbidden && action === 'settle'
784	            ? 'The claim could not be settled: whoever opened it cannot settle it, and your role must be allowed to settle.'
785	            : !forbidden && (action === 'settle' || action === 'approve')
786	              ? `The claim could not be ${PAST[action]}: one due above the proof threshold needs a proof first, and its status must allow it.`
787	            : !forbidden && action === 'open'
788	              ? 'The claim could not be opened: one due above the note threshold needs a note first, and its status and period must allow it.'
789	            : forbidden && action === 'resettle'
790	              ? 'The claim could not be re-settled: only a steward can re-settle a claim.'
791	              : !forbidden && action === 'void' && claim.status === 'SETTLED'
792	                ? 'The claim could not be voided: only a steward voids a settled claim, within 7 days of its settlement and outside a closed period.'
793	              : forbidden
794	                ? action === 'open' || action === 'void'
795	                  ? `The claim could not be ${PAST[action]}: your role may not ${action} a claim on this sheet.`
796	                  : `The claim could not be ${PAST[action]}: only a steward who did not open it can.`
797	              : `The claim could not be ${PAST[action]}.`,
798	      });
799	    }
800	  }
801	
802	  protected async submit(event: Event): Promise<void> {
803	    event.preventDefault();
804	    if (this.busy()) return;
805	    this.error.set(null);
806	    this.rowError.set(null);
807	    const sheet = this.session.sheetId();
808	    if (!sheet) return;
809	    const amount = this.amount().trim();
810	    if (!CLAIM_AMOUNT.test(amount)) {
811	      this.error.set('Type an amount with up to two decimals.');
812	      return;
813	    }
814	    const corrects = this.corrects().trim();
815	    const negative = amount.startsWith('-') && Number(amount) !== 0;
816	    if (negative && !NUMBER.test(corrects)) {
817	      this.error.set('A negative amount is a correction: type the number of the settled claim it corrects.');
818	      return;
819	    }
820	    if (!negative && corrects !== '') {
821	      this.error.set('Only a negative amount corrects a claim: leave the claim number blank.');
822	      return;
823	    }
824	    const body = {
825	      amount,
826	      date: this.date().trim() || null,
827	      note: this.note().trim(),
828	      corrects: corrects === '' ? null : corrects,
829	    };
830	    const id = this.editingId();
831	    const base = `/api/sheets/${encodeURIComponent(sheet)}/people/${this.personId()}/claims`;
832	    this.busy.set(true);
833	    try {
834	      const saved = await firstValueFrom(
835	        id === null ? this.http.post<Claim>(base, body) : this.http.put<Claim>(`${base}/${id}`, body),
836	      );
837	      if (this.session.sheetId() !== sheet) return;
838	      this.saved.emit(saved);
839	      this.reset();
840	    } catch {
841	      const what = negative ? 'correction' : 'claim';
842	      this.error.set(id === null ? `The ${what} could not be added.` : `The ${what} could not be saved.`);
843	    } finally {
844	      this.busy.set(false);
845	    }
846	  }
847	}
